      "sourceAnchors": [
        {
          "exactQuote": "29. ( 1 ) Any person aggrieved by an order or direction made by the Board under this Act may prefer an appeal before the Appellate Tribunal.",
          "occurrence": 0,
          "sourceId": "src:356"
        },
        {
          "exactQuote": "( 10 ) In respect of appeals filed under the provisions of this Act, the  Appellate Tribunal shall, as far as practicable, function as a digital office, with the receipt of appeal, hearing and pronouncement of decisions in respect of the same being digital by design.",
          "occurrence": 0,
          "sourceId": "src:370"
        }
      ],
      "titleAnchor": {
        "exactQuote": "Appeal  to Appellate Tribunal.",
        "occurrence": 0,
        "sourceId": "src:360"
